#!/usr/bin/env python3
"""Evaluador de calidad: compara una salida contra tus criterios (API de Anthropic).

Uso:
  python evaluador.py --salida respuesta.txt --criterios criterios.txt
  python evaluador.py --salida respuesta.txt --criterios criterios.txt --contexto pregunta.txt

Requisitos:
  pip install anthropic
  export ANTHROPIC_API_KEY="tu-clave"

Formato de criterios.txt: un criterio por línea. Las líneas que empiezan por
"!" son eliminatorias (nota menor de 5 ahí = no_apto directo). Ejemplo:
  ! No inventa datos que no estén en el contexto
  ! Trata al cliente con respeto en todo momento
  Responde a todo lo que se pregunta
  Tono cercano y profesional, con tuteo
  Menos de 150 palabras
"""

import argparse
import json
import os
import sys
from pathlib import Path

try:
    import anthropic
except ImportError:
    sys.exit("Falta el SDK de Anthropic. Instálalo con: pip install anthropic")

# ── Configuración ───────────────────────────────────────────────────────

MODELO = "claude-sonnet-5"  # juzgar bien pide un modelo fuerte
NOTA_APTO = 7.0      # media ponderada mínima para apto
NOTA_REVISAR = 5.0   # entre esto y NOTA_APTO queda en 'revisar'
MAX_CARACTERES = 40000

SISTEMA = (
    "Eres un evaluador de calidad exigente y justo, en español. "
    "Te doy una SALIDA a evaluar, una lista de CRITERIOS y, a veces, el "
    "CONTEXTO que la originó. Evalúa cada criterio por separado llamando a "
    "la herramienta. Reglas: puntúa de 0 (incumplimiento total) a 10 "
    "(cumplimiento impecable); la evidencia de cada criterio cita texto "
    "literal de la salida (o señala qué falta); no premies la longitud ni "
    "la seguridad del tono: evalúa solo lo que pide el criterio; si un "
    "criterio no aplica a esta salida, puntúa 10 y dilo en la evidencia. "
    "Sé el evaluador que te gustaría tener: duro con los fallos, concreto "
    "en cómo arreglarlos."
)

HERRAMIENTA = {
    "name": "registrar_evaluacion",
    "description": "Registra la evaluación criterio a criterio de la salida.",
    "strict": True,
    "input_schema": {
        "type": "object",
        "properties": {
            "criterios": {
                "type": "array",
                "description": "Un elemento por criterio, en el mismo orden recibido.",
                "items": {
                    "type": "object",
                    "properties": {
                        "criterio": {"type": "string", "description": "El criterio evaluado, literal."},
                        "nota": {"type": "number", "minimum": 0, "maximum": 10},
                        "evidencia": {
                            "type": "string",
                            "description": "Cita o carencia concreta que justifica la nota.",
                        },
                        "mejora": {
                            "type": ["string", "null"],
                            "description": "Qué cambiar para subir nota; null si ya es 10.",
                        },
                    },
                    "required": ["criterio", "nota", "evidencia", "mejora"],
                    "additionalProperties": False,
                },
            },
            "resumen": {
                "type": "string",
                "description": "Valoración global en 2-3 frases.",
            },
        },
        "required": ["criterios", "resumen"],
        "additionalProperties": False,
    },
}

# ── Lógica ──────────────────────────────────────────────────────────────


def leer(ruta: str, obligatorio: bool = True) -> str:
    if not ruta:
        return ""
    try:
        texto = Path(ruta).read_text(encoding="utf-8", errors="replace").strip()
    except OSError as e:
        sys.exit(f"No puedo leer {ruta}: {e}")
    if obligatorio and not texto:
        sys.exit(f"El fichero {ruta} está vacío.")
    return texto


def cargar_criterios(ruta: str) -> list[dict]:
    """Devuelve [{texto, eliminatorio}] a partir del fichero de criterios."""
    criterios = []
    for linea in leer(ruta).splitlines():
        linea = linea.strip()
        if not linea or linea.startswith("#"):
            continue
        eliminatorio = linea.startswith("!")
        criterios.append({"texto": linea.lstrip("! ").strip(), "eliminatorio": eliminatorio})
    if not criterios:
        sys.exit("El fichero de criterios no tiene ningún criterio.")
    return criterios


def evaluar(client: "anthropic.Anthropic", salida: str, criterios: list[dict], contexto: str) -> dict:
    lista = "\n".join(f"{i + 1}. {c['texto']}" for i, c in enumerate(criterios))
    partes = []
    if contexto:
        partes.append(f"CONTEXTO (lo que originó la salida):\n{contexto}")
    partes.append(f"CRITERIOS:\n{lista}")
    partes.append(f"SALIDA A EVALUAR:\n{salida}")
    respuesta = client.messages.create(
        model=MODELO,
        max_tokens=3000,
        system=SISTEMA,
        tools=[HERRAMIENTA],
        tool_choice={"type": "tool", "name": "registrar_evaluacion"},
        messages=[{"role": "user", "content": "\n\n".join(partes)}],
    )
    for bloque in respuesta.content:
        if bloque.type == "tool_use" and bloque.name == "registrar_evaluacion":
            return dict(bloque.input)
    raise RuntimeError("La API no devolvió la evaluación esperada.")


def veredicto_final(evaluacion: dict, criterios: list[dict]) -> dict:
    """El veredicto lo calcula el código con reglas fijas, no el modelo."""
    notas = evaluacion.get("criterios", [])
    expected = [c["texto"] for c in criterios]
    received = [n.get("criterio") for n in notas if isinstance(n, dict)]
    if received != expected or len(set(received)) != len(received):
        return {"veredicto": "revisar", "nota_media": 0.0,
                "eliminatorio_suspendido": False, "criterios": notas,
                "resumen": "Evaluación incompleta o criterios distintos/desordenados: requiere revisión humana."}
    if any(not isinstance(n.get("nota"), (int, float)) or isinstance(n.get("nota"), bool)
           or not 0 <= n["nota"] <= 10 for n in notas):
        return {"veredicto": "revisar", "nota_media": 0.0,
                "eliminatorio_suspendido": False, "criterios": notas,
                "resumen": "Puntuación inválida: requiere revisión humana."}
    eliminatorio_suspendido = False
    suma = 0.0
    for i, item in enumerate(notas):
        nota = float(item.get("nota", 0))
        suma += nota
        es_eliminatorio = i < len(criterios) and criterios[i]["eliminatorio"]
        item["eliminatorio"] = es_eliminatorio
        if es_eliminatorio and nota < 5:
            eliminatorio_suspendido = True
    media = round(suma / len(notas), 2) if notas else 0.0

    if eliminatorio_suspendido:
        veredicto = "no_apto"
    elif media >= NOTA_APTO:
        veredicto = "apto"
    elif media >= NOTA_REVISAR:
        veredicto = "revisar"
    else:
        veredicto = "no_apto"

    return {
        "veredicto": veredicto,
        "nota_media": media,
        "eliminatorio_suspendido": eliminatorio_suspendido,
        "criterios": notas,
        "resumen": evaluacion.get("resumen", ""),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description="Evalúa una salida contra tus criterios.")
    parser.add_argument("--salida", required=True, help="Fichero con el texto a evaluar")
    parser.add_argument("--criterios", required=True, help="Fichero con un criterio por línea ('!' = eliminatorio)")
    parser.add_argument("--contexto", help="Fichero opcional con la pregunta/encargo original")
    args = parser.parse_args()

    if not os.environ.get("ANTHROPIC_API_KEY"):
        sys.exit(
            "Falta la variable de entorno ANTHROPIC_API_KEY.\n"
            "Crea la clave en console.anthropic.com y expórtala antes de ejecutar."
        )

    salida = leer(args.salida)
    contexto = leer(args.contexto, obligatorio=False) if args.contexto else ""
    criterios = cargar_criterios(args.criterios)
    if len(salida) > MAX_CARACTERES:
        print(f"AVISO: salida recortada a {MAX_CARACTERES} caracteres.", file=sys.stderr)
        salida = salida[:MAX_CARACTERES]

    client = anthropic.Anthropic()  # lee ANTHROPIC_API_KEY del entorno

    try:
        evaluacion = evaluar(client, salida, criterios, contexto)
    except anthropic.AuthenticationError:
        sys.exit("Clave de API inválida o revocada. Revisa ANTHROPIC_API_KEY.")
    except anthropic.RateLimitError:
        sys.exit("Límite de peticiones alcanzado. Espera un minuto y reintenta.")
    except anthropic.APIStatusError as e:
        sys.exit(f"Error de la API ({e.status_code}): {e.message}")
    except anthropic.APIConnectionError:
        sys.exit("No hay conexión con la API. Revisa tu red y reintenta.")

    resultado = veredicto_final(evaluacion, criterios)
    print(json.dumps(resultado, ensure_ascii=False, indent=2))

    # Código de salida útil para encadenar: 0 apto, 2 revisar, 3 no_apto.
    sys.exit({"apto": 0, "revisar": 2, "no_apto": 3}[resultado["veredicto"]])


if __name__ == "__main__":
    main()
